begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000008101','ann-admin@test.local'),('00000000-0000-4000-8000-000000008102','ann-parent@test.local'),('00000000-0000-4000-8000-000000008103','ann-other@test.local'),('00000000-0000-4000-8000-000000008104','ann-partner@test.local');
insert into public.operations_members(user_id,role,expires_at) values('00000000-0000-4000-8000-000000008101','release',now()+interval '1 day');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000008101','A','00000000-0000-4000-8000-000000008102'),('10000000-0000-4000-8000-000000008102','B','00000000-0000-4000-8000-000000008103');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000008101','00000000-0000-4000-8000-000000008102'),('10000000-0000-4000-8000-000000008101','00000000-0000-4000-8000-000000008104'),('10000000-0000-4000-8000-000000008102','00000000-0000-4000-8000-000000008103');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000008101','10000000-0000-4000-8000-000000008101','Child A',2),('20000000-0000-4000-8000-000000008102','10000000-0000-4000-8000-000000008101','Child B',3),('20000000-0000-4000-8000-000000008103','10000000-0000-4000-8000-000000008102','Child C',5);
insert into gina.education_places(id,kind,parent_id,name) values('ec000000-0000-4000-8000-000000008101','region','ec000000-0000-4000-8000-000000000001','Ankara QA'),('ec000000-0000-4000-8000-000000008102','school','ec000000-0000-4000-8000-000000008101','School QA');
insert into gina.child_education_locations(child_id,place_id,stage) values('20000000-0000-4000-8000-000000008101','ec000000-0000-4000-8000-000000008102','primary'),('20000000-0000-4000-8000-000000008102','ec000000-0000-4000-8000-000000008102','primary'),('20000000-0000-4000-8000-000000008103','ec000000-0000-4000-8000-000000000001','middle');
insert into auth.sessions(id,user_id) values(gen_random_uuid(),'00000000-0000-4000-8000-000000008102'),(gen_random_uuid(),'00000000-0000-4000-8000-000000008104');
insert into public.push_tokens(user_id,family_id,role,platform,token,token_type) values('00000000-0000-4000-8000-000000008102','10000000-0000-4000-8000-000000008101','parent','ios','qa-ann-parent','apns'),('00000000-0000-4000-8000-000000008104','10000000-0000-4000-8000-000000008101','parent','ios','qa-ann-partner','apns');
create function pg_temp.ann() returns uuid language sql as $$select 'aa000000-0000-4000-8000-000000008101'::uuid$$;
create function pg_temp.value() returns jsonb language sql as $$select jsonb_build_object('title','Regional school notice','body','Please review the school announcement.','place_id','ec000000-0000-4000-8000-000000008101','stage','primary','push',true,'expires_on',current_date+7)$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008101","role":"authenticated","gina":{"role":"parent"}}',true);
select lives_ok($$select public.admin_save_announcement('70000000-0000-4000-8000-000000008101',pg_temp.ann(),0,pg_temp.value())$$,'release operator saves draft');
select lives_ok($$select public.admin_save_announcement('70000000-0000-4000-8000-000000008101',pg_temp.ann(),0,pg_temp.value())$$,'draft retry idempotent');
select is(public.admin_preview_announcement(pg_temp.ann(),1)->>'count','2','two parents, not two children times two parents');
select throws_ok($$select public.admin_publish_announcement(gen_random_uuid(),pg_temp.ann(),1,'bad',true)$$,'P0001','announcement_audience_changed','audience mismatch requires new preview');
select throws_ok($$select public.admin_publish_announcement(gen_random_uuid(),pg_temp.ann(),1,'bad',false)$$,'P0001','announcement_confirmation','explicit confirmation required');
select set_config('test.fingerprint',public.admin_preview_announcement(pg_temp.ann(),1)->>'fingerprint',true);
reset role;
select is((select count(*)::int from gina.parent_inbox),0,'draft and preview do not send');
select is((select count(*)::int from public.push_outbox where kind='parent_announcement'),0,'failed publish leaves no queue entries');
set local role authenticated;
select lives_ok($$select public.admin_publish_announcement('70000000-0000-4000-8000-000000008102',pg_temp.ann(),1,current_setting('test.fingerprint'),true)$$,'published to snapshot audience');
select lives_ok($$select public.admin_publish_announcement('70000000-0000-4000-8000-000000008102',pg_temp.ann(),1,current_setting('test.fingerprint'),true)$$,'publish retry returns receipt');
select throws_ok($$select public.admin_save_announcement(gen_random_uuid(),pg_temp.ann(),2,pg_temp.value())$$,'P0001','announcement_changed','published content cannot be edited silently');
reset role;
select is((select count(*)::int from gina.parent_inbox),2,'one inbox record per parent');
select is((select count(*)::int from public.push_outbox where kind='parent_announcement'),2,'one push event per parent');
select is((select count(*)::int from public.push_targets((select id from public.push_outbox where target_user_id='00000000-0000-4000-8000-000000008102'))),1,'push cannot broadcast to the other family parent');
insert into public.push_preferences(user_id,family_id,announcements) values('00000000-0000-4000-8000-000000008104','10000000-0000-4000-8000-000000008101',false);
select is((select count(*)::int from public.push_targets((select id from public.push_outbox where target_user_id='00000000-0000-4000-8000-000000008104'))),0,'push opt-out honored independently of inbox');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008102","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000008101"}}',true);
select is(public.parent_inbox()->>'unread','1','parent sees own unread count');
select is(jsonb_array_length(public.parent_inbox()->'rows'),1,'parent sees only their own recipient copy');
select set_config('test.inbox',public.parent_inbox()->'rows'->0->>'id',true);
select lives_ok($$select public.mark_parent_inbox(current_setting('test.inbox')::uuid,null)$$,'read marking succeeds');
select is(public.parent_inbox()->>'unread','0','read status is explicit');
select lives_ok($$select public.mark_parent_inbox(current_setting('test.inbox')::uuid,true)$$,'parent may archive');
select is(jsonb_array_length(public.parent_inbox()->'rows'),0,'archive hides from current view');
select is(jsonb_array_length(public.parent_inbox(null,null,true)->'rows'),1,'archive remains recoverable');
select lives_ok($$select public.mark_parent_inbox(current_setting('test.inbox')::uuid,false)$$,'restore is explicit');
select throws_ok($$select public.admin_announcements()$$,'42501','forbidden','parent has no release access');
select ok(not has_table_privilege('authenticated','gina.parent_inbox','SELECT'),'direct inbox table is private');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008103","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000008102"}}',true);
select is(jsonb_array_length(public.parent_inbox()->'rows'),0,'nonmatching region/stage not targeted');
select throws_ok($$select public.mark_parent_inbox(current_setting('test.inbox')::uuid,true)$$,'P0001','not_found','cannot mark another parent inbox');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008102","role":"authenticated","gina":{"role":"device","family_id":"10000000-0000-4000-8000-000000008101"}}',true);
select throws_ok($$select public.parent_inbox()$$,'42501','forbidden','child device cannot read parent notices');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008101","role":"authenticated","gina":{"role":"parent"}}',true);
select lives_ok($$select public.admin_withdraw_announcement('70000000-0000-4000-8000-000000008103',pg_temp.ann(),2)$$,'withdraw explicit');
select lives_ok($$select public.admin_withdraw_announcement('70000000-0000-4000-8000-000000008103',pg_temp.ann(),2)$$,'withdraw retry safe');
reset role;
select is((select count(*)::int from public.push_outbox where kind='parent_announcement' and status='no_targets'),2,'withdraw stops queued push');
select is((select count(*)::int from public.push_targets((select id from public.push_outbox where target_user_id='00000000-0000-4000-8000-000000008102'))),0,'withdraw blocks delivery recheck');
-- Calendar boundaries are advisory, unique by child/year/boundary, never promotions.
select is(gina.enqueue_education_reminders(),0,'reminders are off by default');
update gina.education_notification_settings set reminders_enabled=true;
insert into gina.education_calendars(id,place_id,stage,academic_year,draft,published,published_revision) values('ca000000-0000-4000-8000-000000008101','ec000000-0000-4000-8000-000000008101','primary',extract(year from current_date)::int,'{}',jsonb_build_object('title','QA calendar','starts_on',current_date,'ends_on',current_date+180),1);
select is(gina.enqueue_education_reminders(),4,'two children get one reminder per parent');
select is(gina.enqueue_education_reminders(),0,'same boundary never duplicated');
update gina.education_calendars set published_revision=2 where id='ca000000-0000-4000-8000-000000008101';
select is(gina.enqueue_education_reminders(),0,'calendar revision does not spam reminders');
select is((select grade::int from public.children where id='20000000-0000-4000-8000-000000008101'),2,'reminder never changes grade');
select is((select count(*)::int from gina.child_education_periods),0,'reminder does not invent education records');
insert into gina.child_education_periods(child_id,family_id,academic_year,grade,starts_on,reason) values('20000000-0000-4000-8000-000000008101','10000000-0000-4000-8000-000000008101',extract(year from current_date)::int,2,current_date,'initial');
select is(gina.inbox_push_current((select id::text from gina.parent_inbox where child_id='20000000-0000-4000-8000-000000008101' and user_id='00000000-0000-4000-8000-000000008102'),'00000000-0000-4000-8000-000000008102','10000000-0000-4000-8000-000000008101'),false,'pending start push suppressed after parent updates education record');
-- Stable cursor handles multiple rows with the same creation timestamp.
insert into gina.parent_announcements(title,body,expires_on) select 'Paging notice '||n,'Synthetic pagination fixture',current_date+7 from generate_series(1,31)n;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008101","role":"authenticated","gina":{"role":"parent"}}',true);
select is(jsonb_array_length(public.admin_announcements()->'rows'),30,'admin history has a bounded page');
select set_config('test.before',public.admin_announcements()->'rows'->29->>'created_at',true);
select set_config('test.before_id',public.admin_announcements()->'rows'->29->>'id',true);
select is(jsonb_array_length(public.admin_announcements(current_setting('test.before')::timestamptz,current_setting('test.before_id')::uuid)->'rows'),2,'older history remains accessible with timestamp and id cursor');
reset role;
delete from public.family_members where user_id='00000000-0000-4000-8000-000000008102';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000008102","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000008101"}}',true);
select throws_ok($$select public.parent_inbox()$$,'42501','forbidden','removed family member cannot read inbox with stale JWT');
select * from finish();rollback;
